/** English source dictionary (the translate script reads it). */
export const VOICE_EN: VoiceUiCopy = en;

export type VoiceUiCopyTranslation = Translation<VoiceUiCopy>;

/** Placeholder names of the function-valued entries. */
export const VOICE_COPY_PARAMS: ParamNames = { messages: ["n"], remove: ["label"] };

const cache = new Map<string, VoiceUiCopy>();

export function voiceUiCopy(locale: string): VoiceUiCopy {
  if (locale.startsWith("hi")) return hi;
  const hit = cache.get(locale);
  if (hit) return hit;
  const tr = (VOICE_TRANSLATIONS as Record<string, VoiceUiCopyTranslation | undefined>)[locale];
  const copy = tr ? localize(en, tr, VOICE_COPY_PARAMS) : en;
  cache.set(locale, copy);
  return copy;
}
